{
  "packet_id": "H6-T01-1",
  "claim_id": "C017",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C017.component",
    "value": "Under the provisional persistence rule, the same stage must account for the greatest documented delay burden in both investigation weeks.",
    "scope": "A joint requirement with recurrence on multiple booking days in each week. The measure of delay burden and treatment of ties are unspecified.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P011 explicitly supplies the same-stage ranking requirement together with recurrence in each week, without specifying the burden measure or tie handling."
    }
  },
  "signal_basis": {
    "component_id": "C017.signal_basis",
    "value": "Repeated booking observations show a candidate bottleneck recurring on multiple days in each investigation week, with the same stage having the greatest documented delay burden in both weekly summaries.",
    "scope": "The two-week prospective sequence, summarized using delay minutes and stage-specific counts. Ranking-sensitive missing records or insufficient bookings prevent establishing a bottleneck under this practical selection rule; the rule provides neither statistical proof nor causal identification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the weekly measurements, joint persistence conditions, missingness and sparsity restrictions, and explicit limits on the rule's evidential force."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C017.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the judgment is SUPPORTED."
    }
  },
  "rationale": "The frozen claim states a necessary condition of the expressly adopted provisional rule. That rule directly licenses the requirement that the same stage rank greatest in both weeks, jointly with recurrence. The claim does not assert that satisfying this criterion proves an enduring or causal bottleneck.",
  "uncertainty": "The undefined burden measure and tie handling can make particular rankings ambiguous, but do not undermine this accurately stated requirement of the rule.",
  "anomalies": []
}
